html:
{%- set campus_display_name = frappe.db.get_value("Campus", doc.campus, "campus_name") if doc.campus else (doc.campus or "Institution of Legal Education") -%}
{%- set campus_logo_path = frappe.db.get_value("Campus", doc.campus, "logo") if doc.campus else None -%}
{%- set admit_no = doc.admit_card_number or ("AC-" + doc.name) -%}
{%- set dob = frappe.utils.formatdate(doc.date_of_birth) if doc.date_of_birth else "—" -%}

{%- set _site = frappe.utils.get_url() -%}

{#- PRODUCTION IMAGE HANDLER -#}
{%- set _logo_src = '' -%}
{%- if campus_logo_path -%}
    {%- set _lb64 = get_file_b64(campus_logo_path) -%}
    {%- if _lb64 -%}
        {%- set _lext = (campus_logo_path.split('.')[-1] | lower) -%}
        {%- set _lmime = 'image/jpeg' if _lext in ['jpg','jpeg'] else ('image/png' if _lext == 'png' else 'image/svg+xml') -%}
        {%- set _logo_src = 'data:' ~ _lmime ~ ';base64,' ~ _lb64 -%}
    {%- else -%}{%- set _logo_src = _site ~ campus_logo_path -%}{%- endif -%}
{%- endif -%}

{%- set _photo_src = '' -%}
{%- if doc.profile -%}
    {%- set _pb64 = get_file_b64(doc.profile) -%}
    {%- if _pb64 -%}
        {%- set _pext = (doc.profile.split('.')[-1] | lower) -%}
        {%- set _pmime = 'image/jpeg' if _pext in ['jpg','jpeg'] else ('image/png' if _pext == 'png' else 'image/webp') -%}
        {%- set _photo_src = 'data:' ~ _pmime ~ ';base64,' ~ _pb64 -%}
    {%- else -%}{%- set _photo_src = _site ~ doc.profile -%}{%- endif -%}
{%- endif -%}

<!DOCTYPE html>
<html>
<head>
<link href="https://fonts.googleapis.com/css2?family=Merriweather:ital,wght@0,300;0,400;0,700;1,300;1,400;1,700&display=swap" rel="stylesheet">
<meta charset="UTF-8"/>
<style>
    * { box-sizing: border-box; -moz-box-sizing: border-box; }
    @page { size: A4; margin: 8mm; }
    html, body { margin: 0 !important; padding: 0 !important; background: #fff !important; width: 100%; height: 100%; }
    body { font-family: 'Merriweather', serif; font-size: 10.5px; color: #000; line-height: 1.25; }

    .result-card { 
        width: 100%; 
        max-width: 190mm; 
        margin: 0 auto; 
        border: 1.5px solid #444; 
        background: #fff; 
        overflow: hidden; 
        page-break-inside: avoid;
    }

    table { width: 100%; border-collapse: collapse; table-layout: fixed; border-spacing: 0; }
    td { vertical-align: top; padding: 0; }

    /* Header */
    .hdr-bg { background: #7b1c1c !important; color: #ffffff !important; border-bottom: 3px solid #5a0e0e; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .univ-name { font-size: 16px; font-weight: bold; text-transform: uppercase; color: #ffffff !important; }
    .univ-sub { font-size: 8.5px; color: #ffffff !important; opacity: 0.9; letter-spacing: 0.5px; }

    /* Title */
    .title-strip { border-bottom: 1.2px solid #bbb; text-align: center; padding: 6px 0; background: #fdfdfd !important; }
    .t1 { font-size: 14.5px; font-weight: bold; color: #000; }

    /* Main Body */
    .main-body { padding: 10px 15px; }

    /* Master Table Styling */
    .master-tbl { 
        width: 100%; 
        border: 1.5px solid #333; 
        table-layout: fixed; 
        border-collapse: collapse;
        margin-bottom: 0;
    }
    .master-tbl td { 
        border: 1px solid #888; 
        padding: 7px 12px; 
        font-size: 11px; 
        vertical-align: middle; 
        word-wrap: break-word;
    }

    /* Section Headers in Master Table */
    .master-tbl .sec-row td { 
        background: #f4f4f4 !important; 
        text-align: center; 
        font-weight: bold; 
        font-size: 12px; 
        color: #000;
        padding: 8px;
        -webkit-print-color-adjust: exact;
    }

    .master-tbl .lb { 
        font-weight: bold; 
        background: #fcfcfc !important; 
        width: 35%; 
        color: #222;
    }
    .master-tbl .vl { 
        width: 40%; 
        color: #000;
    }
    .master-tbl .ph-col { 
        width: 25%; 
        text-align: center; 
        vertical-align: top; 
        padding: 10px 5px;
    }

    /* Photo Box inside table */
    .ph-box { 
        width: 100px; 
        height: 125px; 
        border: 1px solid #444; 
        background: #eee; 
        margin: 0 auto 5px; 
        overflow: hidden; 
    }
    .ph-label { font-size: 8.5px; font-style: italic; color: #666; }

    /* Status Row */
    .status-row td { 
        text-align: center; 
        padding: 12px; 
        font-size: 14px; 
        font-weight: bold; 
    }

    .footer-tbl { border-top: 1px solid #eee; padding: 8px 10px; font-size: 8.5px; color: #777; width: 100%; }

    /* Force page break prevention */
    .no-break { page-break-inside: avoid; break-inside: avoid; }
</style>
</head>
<body>

<div class="result-card">
    <table class="hdr-bg">
        <tr>
            <td style="width: 85px; padding: 8px 12px; vertical-align: middle;">
                <div style="background:#fff; width:60px; height:60px; border-radius:3px; overflow:hidden; text-align: center; position: relative;">
                    {% if _logo_src %}
                        <img src="{{ _logo_src }}" style="max-width:100%; max-height:100%; position: absolute; top: 0; bottom: 0; left: 0; right: 0; margin: auto;">
                    {% else %}
                        <div style="color:#7b1c1c; font-weight:bold; text-align:center; line-height:60px; font-size:10px;">LOGO</div>
                    {% endif %}
                </div>
            </td>
            <td style="padding: 8px 0; text-align: center; vertical-align: middle;">
                <div class="univ-name">{{ campus_display_name }}</div>
            </td>
            <td style="width: 85px;"></td>
        </tr>
    </table>

    <div class="title-strip">
        <div class="t1">Entrance Test Result Card</div>
        <div style="font-size: 10.5px; color: #666; margin-top: 3px;">{{ doc.entrance_test_name or doc.entrance_test_list or "—" }}</div>
    </div>

    <div class="main-body">
        <table class="master-tbl">
            <!-- CANDIDATE INFORMATION -->
            <tr class="sec-row">
                <td colspan="3">Candidate Information</td>
            </tr>
            <tr>
                <td class="lb">Application Number</td>
                <td class="vl"><strong>{{ doc.applicant or "—" }}</strong></td>
                <td class="ph-col" rowspan="7">
                    <div class="ph-box">
                        {% if _photo_src %}<img src="{{ _photo_src }}" style="width:100%; height:100%; object-fit:cover;">
                        {% else %}<div style="line-height:125px; font-size:40px; color:#ccc;">👤</div>{% endif %}
                    </div>
                    <div class="ph-label">Candidate's Photograph</div>
                </td>
            </tr>
            <tr>
                <td class="lb">Admit Card Number</td>
                <td class="vl">{{ admit_no }}</td>
            </tr>
            <tr>
                <td class="lb">Name of the Candidate</td>
                <td class="vl">{{ doc.candidate_name or "—" }}</td>
            </tr>
            <tr>
                <td class="lb">Programme</td>
                <td class="vl">{{ doc.program or "—" }}</td>
            </tr>
            <tr>
                <td class="lb">Date of Birth</td>
                <td class="vl">{{ dob }}</td>
            </tr>
            <tr>
                <td class="lb">Academic Year</td>
                <td class="vl">{{ doc.academic_year or "—" }}</td>
            </tr>
            <tr>
                <td class="lb">Admission Cycle</td>
                <td class="vl">{{ doc.admission_cycle or "—" }}</td>
            </tr>

            <!-- PART A -->
            <tr class="sec-row">
                <td colspan="3">Part A</td>
            </tr>
            <tr>
                <td class="lb">Total Marks Scored</td>
                <td colspan="2" class="vl">{{ doc.part_a_total_marks_scored or 0 }}</td>
            </tr>
            <tr>
                <td class="lb">All India Rank</td>
                <td colspan="2" class="vl">{{ doc.part_a_all_india_rank or "—" }}</td>
            </tr>

            <!-- PART B -->
            <tr class="sec-row">
                <td colspan="3">Part B</td>
            </tr>
            <tr>
                <td class="lb">Total Marks Scored</td>
                <td colspan="2" class="vl">{{ doc.part_b_total_marks_scored or 0 }}</td>
            </tr>
            <tr>
                <td class="lb">All India Rank</td>
                <td colspan="2" class="vl">{{ doc.part_b_all_india_rank or "—" }}</td>
            </tr>

            <!-- CUMULATIVE SCORE -->
            <tr class="sec-row">
                <td colspan="3">Cumulative Score (Part A + Part B)</td>
            </tr>
            <tr>
                <td class="lb">Total Marks Secured</td>
                <td colspan="2" class="vl"><strong>{{ doc.total_marks_secured_in_part_a_b or 0 }} / {{ doc.total_marks or 0 }}</strong></td>
            </tr>
            <tr>
                <td class="lb">Percentage</td>
                <td colspan="2" class="vl">{{ "%.2f" | format(doc.percentage or 0) }}%</td>
            </tr>
            <tr>
                <td class="lb">Percentile</td>
                <td colspan="2" class="vl"><strong>{{ doc.percentile or 0 }}%</strong></td>
            </tr>
            <tr>
                <td class="lb">Cumulative Rank</td>
                <td colspan="2" class="vl"><strong>{{ doc.entrance_test_rank or "—" }}</strong></td>
            </tr>

            <!-- FINAL STATUS -->
            <tr class="status-row">
                <td class="lb">Final Result Status</td>
                <td colspan="2" style="text-align: left;">
                    {% if doc.result_status == "Pass" %}
                        <span style="color: #166534; font-size: 15px;">PASS</span>
                    {% elif doc.result_status == "Fail" %}
                        <span style="color: #991b1b; font-size: 15px;">FAIL</span>
                    {% else %}
                        <span style="color: #334155; font-size: 15px;">{{ (doc.result_status or "Declared") | upper }}</span>
                    {% endif %}
                </td>
            </tr>
        </table>
    </div>

    <table class="footer-tbl">
        <tr>
            <td style="text-align: left; padding: 0 10px;">Report generated on {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "dd-MM-yyyy HH:mm") }}</td>
            <td style="text-align: right; padding: 0 10px;">Authenticated Digitally &middot; Office of Admissions</td>
        </tr>
    </table>
</div>

</body>
</html>
